INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'single', 2, '{"stem": "选择(1)：李老师买了5个单价58元的篮球，付给售货员300元。下面（ ）可以用估算解决。A. 李老师付300元够不够？  B. 售货员应该收多少钱？  C. 售货员应该找回多少钱？  D. 李老师买完后还剩多少钱？"}', 'A', '估算58≈60, 5×60=300, 用于判断够不够', 'jsj3_sx_v100', '["jsj3_sx","U2","p030","choice_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'single', 2, '{"stem": "选择(2)：甲数=260×3，乙数=26×30，甲数和乙数相比，结果是（ ）。A. 两数相等  B. 甲数大  C. 乙数大  D. 无法确定"}', 'A', '260×3=780, 26×30=780, 两数相等', 'jsj3_sx_v100', '["jsj3_sx","U2","p030","choice_02"]', 1, NULL);
