INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'apply', 2, '{"stem": "应用(3)：小明和4个好朋友一起去看儿童剧，每张门票105元，他们一共要付多少元？（6分）"}', '525（元）', '1+4=5（人）, 105×5=525（元）', 'jsj3_sx_v100', '["jsj3_sx","U2","p031","apply_03"]', 1, NULL);
