INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展：一筐香蕉12千克，每千克售价8元，卖出一半后，又卖出余下部分的一半，这样一共收到多少钱？（10分）"}', '72（元）', '卖出一半：12÷2=6（千克）, 6×8=48（元）; 再卖出余下一半：6÷2=3（千克）, 3×8=24（元）; 共收到：48+24=72（元）', 'jsj3_sx_v100', '["jsj3_sx","U2","p031","think_01"]', 1, NULL);